using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Launch;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
public sealed class RaceAiPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--race-ai-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=folder+"/isolated.json";}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder!=null){var go=new GameObject("Isolated native race opponent verification");DontDestroyOnLoad(go);go.AddComponent<RaceAiPlayerProbe>();}}
 void Check(bool ok,string text){checks.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!ok){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string t,string trace,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+t);}void Update(){if(deadline>0&&Time.realtimeSinceStartupAsDouble>deadline&&!failed)Check(false,"Native opponent timeout");}
 IEnumerator Wait(Func<bool> condition){while(!condition())yield return null;yield return new WaitForSecondsRealtime(.2f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/"+name+".png");yield return new WaitForSecondsRealtime(.4f);Check(new FileInfo(folder+"/"+name+".png").Length>50000,"Actual native render: "+name);}
 IEnumerator Start(){Application.runInBackground=true;deadline=Time.realtimeSinceStartupAsDouble+210;yield return Wait(()=>HarborValeLaunch.Instance!=null);HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene);yield return Wait(()=>RivalRaceDirector.Instance?.Ready==true);var director=RivalRaceDirector.Instance;var car=director.Trial.vehicle;car.externalInput=true;car.commandedHandbrake=false;car.commandedServiceBrake=1;yield return new WaitForSecondsRealtime(13);var traffic=FindAnyObjectByType<TrafficWorld>();Check(traffic.Spawned>=6&&TrafficWorld.Agents.Where(p=>!p.IsRival).Any(p=>p.DistanceMoved>10),"Ambient traffic is physical and moving before race");Check(director.OpenPanel(),"Real H race panel opens");director.SelectedRival="club";Check(director.StartRace()&&director.Race.Contract.speedKph==85,"New club contract records85kmh cap with unchanged cash terms");Check(director.Race.Contract.winCredits==1000&&director.Race.Contract.finishCredits==200,"AI difficulty change preserves money terms");var camera=Camera.main.GetComponent<FinchChaseCamera>();camera.target=director.Opponent.Car;camera.Snap();Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);Time.timeScale=3;int full=0;float peak=0;bool captured=false;while(!director.Race.Rival.ValidFinish&&!director.Results){var p=director.Opponent;peak=Mathf.Max(peak,p.Car.SpeedKph);if(p.Car.commandedPedal>=.999f)full++;if(!captured&&director.Race.Rival.NextGate>=7){captured=true;yield return Capture("Race_Opponent_In_Traffic");}yield return null;}
 Time.timeScale=1;var rival=director.Opponent;Check(director.Race.Rival.ValidFinish&&director.Race.Rival.NextGate==37,"Real native opponent completes all37 ordered city gates with ambient traffic");Check(rival.Recoveries==0,"Native opponent completes circuit without assisted teleport recovery");Check(full>20&&peak>75,"Native rival actually uses full throttle and exceeds75kmh");File.WriteAllText(folder+"/measurements.json",JsonUtility.ToJson(new Measures{peakKph=peak,fullThrottleFrames=full,overtakes=rival.Overtakes,recoveries=rival.Recoveries,elapsed=director.Race.Rival.Elapsed},true));yield return Capture("Race_Opponent_Finish");Check(director.BeforeLeave(),"Native cash race can close with normal atomic forfeit");Check(director.Trial.Store.Profile.availableCredits==0,"Stationary test player receives no fabricated finish reward");string saved=File.ReadAllText(director.Trial.Store.PathName);Check(new RaceProgressStore(director.Trial.Store.PathName,director.Trial.Definition).Profile.availableCredits==0,"Real race ledger reload validates after AI run");Check(!failed,"Race AI native verification has no runtime errors");Application.Quit(0);}
 [Serializable]class Measures{public float peakKph,elapsed;public int fullThrottleFrames,overtakes,recoveries;}
}
}
